import React from 'react';
import slider from './slider.png';
import pointer from './Ellipse.png';
import './weatherWidget.css';
export default function WeatherWidget({Icon, Heading, Value,Description, Percentage}){

return (
    <div class="widget">
        <div class="widgetHeading">
            <img src={Icon} alt="widget icon" />
            <section>{Heading}</section>
        </div>
        <div class="valueSection">
            {Value}
        </div>

        <section id="desc">
            {Description}
        </section>

        <div>
            <img src={slider} alt='slider' id="slider"></img>
            <img src ={pointer} alt='pointer' id="pointer" style={{left:10}}></img>
        </div>

    </div>
)

}
